"""SQLAlchemy 2 models of every ARCILOGGER table (build specification 7.3, 8.5, 9, 13).

Rules that hold for every table:

* Times are ``TIMESTAMP WITH TIME ZONE`` and always aware (UTC in the database session).
* IP addresses are ``INET``, networks ``CIDR``, MAC addresses ``MACADDR``; unknown or extra
  fields go to a ``JSONB`` column named ``extra``.
* Generated ids are ``BIGINT GENERATED BY DEFAULT AS IDENTITY``.

**Time-series tables** (``messages``, ``fg_*``, ``mt_*``) share the columns of
:class:`TimeSeries`. Their primary key is ``(time, id)`` because on a TimescaleDB hypertable every
unique index must contain the partitioning column; the same schema works on plain PostgreSQL.
Every time-series row points back to its raw line: ``(source, raw_day, raw_line, raw_offset)``
names line ``raw_line`` (1-based) of ``spool/<source>/<raw_day>.log``, which starts at byte
``raw_offset``. After sealing, the same line is at the same position in the decompressed
``vault/<Y>/<M>/<D>/<source>.log.gz``.

Column names follow section 7.3 of the specification where it names them, so parser authors can
work from the specification. SQL keywords are avoided as column names (``user`` → ``user_name``);
the exceptions taken from the specification are ``leases.start`` / ``leases."end"``.
"""

from __future__ import annotations

import uuid
from datetime import date, datetime
from typing import Any, Final

from sqlalchemy import (
    BigInteger,
    Boolean,
    CheckConstraint,
    Date,
    ForeignKey,
    Identity,
    Index,
    Integer,
    MetaData,
    PrimaryKeyConstraint,
    SmallInteger,
    Text,
    UniqueConstraint,
    func,
    text,
)
from sqlalchemy.dialects.postgresql import (
    ARRAY,
    BYTEA,
    CIDR,
    DOUBLE_PRECISION,
    INET,
    JSONB,
    MACADDR,
    TIMESTAMP,
    UUID,
)
from sqlalchemy.orm import DeclarativeBase, Mapped, mapped_column

from arcilogger_core.admin.contract import ADMIN_REQUEST_KINDS, SECTIONS, STATES, TERMINAL_STATES

TZ = TIMESTAMP(timezone=True)

#: Deterministic constraint and index names: migrations stay stable across machines.
NAMING_CONVENTION: Final = {
    "ix": "ix_%(table_name)s_%(column_0_N_name)s",
    "uq": "uq_%(table_name)s_%(column_0_N_name)s",
    "ck": "ck_%(table_name)s_%(constraint_name)s",
    "fk": "fk_%(table_name)s_%(column_0_N_name)s_%(referred_table_name)s",
    "pk": "pk_%(table_name)s",
}

ROLES: Final = ("admin", "auditor", "hr", "viewer")
SOURCE_TYPES: Final = ("fortigate", "mikrotik", "generic")
LEASE_END_REASONS: Final = ("dhcp", "timeout", "superseded", "arp", "open")
CONFIDENCE_LEVELS: Final = ("high", "medium", "low")
DEVICE_TYPES: Final = ("pc", "phone", "printer", "ip_phone", "ap", "server", "camera", "other")
ALERT_SEVERITIES: Final = ("info", "low", "medium", "high", "critical")
ALERT_STATES: Final = ("open", "acknowledged", "resolved", "dismissed")
JOB_STATUSES: Final = ("running", "ok", "failed", "skipped")
LOOKUP_MODES: Final = ("exact", "candidates", "internal", "none")
#: Time stamp of an official lookup report (setting ``lookup.report_timestamp``).
REPORT_TIMESTAMP_STATUSES: Final = ("not_requested", "stamped", "failed")
#: ``queued`` → ``building`` → ``ready`` | ``failed``; later ``expired`` (purged after
#: ``evidence.keep_days``) or ``deleted`` (the file vanished from ``exports/``).
EVIDENCE_STATUSES: Final = ("queued", "building", "ready", "failed", "expired", "deleted")
#: On-demand seal verification results (``seal_verifications.outcome``).
SEAL_VERIFY_OUTCOMES: Final = ("ok", "failed", "timeout", "error")
#: Area E (alert e-mail, ADR-0010): what an ``alert_deliveries`` row announces, and its state.
#: ``suppressed``: not e-mailed because of ``alerts.email_max_per_hour``; counted in the next
#: summary e-mail (``message_id`` set once it was).
ALERT_DELIVERY_KINDS: Final = ("new", "resolved")
ALERT_DELIVERY_STATUSES: Final = ("queued", "sent", "failed", "suppressed")
#: Area U (usage analytics, ADR-0011): who a usage row belongs to — the person the device was
#: assigned to at that moment, else the device (MAC of the lease), else the bare IP address.
USAGE_SUBJECT_KINDS: Final = ("person", "device", "ip")
#: How a session's destination was named (spec 10.2): a host name (web filter, application
#: control / SSL, DNS answer), a FortiGuard ISDB service (``dstinetsvc``) or only the address.
USAGE_DOMAIN_KINDS: Final = ("domain", "service", "ip")
#: ``partial``: today (refreshed every 5 minutes); ``final``: rebuilt after the day ended.
USAGE_DAY_STATUSES: Final = ("partial", "final")
USAGE_BLOCKED_SOURCES: Final = ("web", "dns", "app")
USAGE_REBUILD_STATUSES: Final = ("queued", "running", "done", "failed")
#: Where a ``domain_categories`` entry comes from: the web filter's or the DNS filter's category.
DOMAIN_CATEGORY_SOURCES: Final = ("web", "dns")

#: Area S (alert workflow, ADR-0010 amendment): an ``alert_events`` row is a change of state or
#: a note; a note holds 1-2000 characters, the reason code of an automatic change at most 200.
ALERT_EVENT_KINDS: Final = ("state", "note")
ALERT_NOTE_MAX: Final = 2000
ALERT_REASON_MAX: Final = 200

#: Area R (scheduled usage reports, ADR-0012): what a schedule produces and when; a run of a
#: schedule with a period given by hand is ``custom``.
REPORT_SCHEDULE_KINDS: Final = ("end_of_day", "full_day", "weekly", "monthly")
REPORT_RUN_KINDS: Final = (*REPORT_SCHEDULE_KINDS, "custom")
#: ``queued`` → ``running`` (rendering, then delivering and retrying) → ``sent`` (finished:
#: every due e-mail went out), ``partial`` (some recipients failed for good) or ``failed``.
REPORT_RUN_STATUSES: Final = ("queued", "running", "sent", "partial", "failed")
REPORT_TRIGGERS: Final = ("schedule", "manual")

#: Offline licensing (licensing contract 4.1): what a ``license_events`` row records, and who
#: wrote it (the API, ``arcilogger-db license``, the worker's ``license.check``, the seed).
LICENSE_EVENT_KINDS: Final = ("install", "remove", "refuse", "limit", "state")
LICENSE_SOURCES: Final = ("web", "cli", "worker", "seed")
#: Largest licence file (bytes) ``license_files.content`` holds (``license_too_large`` above).
LICENSE_MAX_BYTES: Final = 65536

#: Browser administration (ADR-0014, contract 2.15): who carries a request out — the agent
#: ``ArciAdmin`` (a signed request file) or the worker (the non-secret actions it takes from
#: ``admin_requests`` itself: test e-mail, lease rebuild).
ADMIN_REQUEST_CHANNELS: Final = ("agent", "worker")
#: A key of ``admin_requests.params`` / ``result`` named like this (case-insensitive) holds a
#: masked secret (``{"secret": true, "old": "set", …}``), never a value: no secret ever enters
#: the database (ADR-0009 §6), checked by the database itself (``ck_admin_requests_*_masked``).
SECRET_KEY_PATTERN: Final = "password|customer|token"  # noqa: S105 - key names, no secret


def _in(column: str, values: tuple[str, ...]) -> str:
    quoted = ", ".join(f"'{value}'" for value in values)
    return f"{column} IN ({quoted})"


class Base(DeclarativeBase):
    metadata = MetaData(naming_convention=NAMING_CONVENTION)


def _created() -> Mapped[datetime]:
    return mapped_column(TZ, nullable=False, server_default=func.now(), sort_order=900)


def _updated() -> Mapped[datetime]:
    return mapped_column(
        TZ, nullable=False, server_default=func.now(), onupdate=func.now(), sort_order=901
    )


# =================================================================================================
# Time-series tables (TimescaleDB hypertables when available, plain tables otherwise)
# =================================================================================================


class TimeSeries:
    """Columns shared by every time-series table.

    ``time`` is the device/event time in UTC (FortiGate ``eventtime`` preferred, MikroTik
    header time); when a message carries no usable device time it equals ``time_received``.
    """

    id: Mapped[int] = mapped_column(BigInteger, Identity(), nullable=False, sort_order=-100)
    time: Mapped[datetime] = mapped_column(TZ, nullable=False, sort_order=-99)
    #: Collector receive time (the prefix of the raw spool line).
    time_received: Mapped[datetime] = mapped_column(TZ, nullable=False, sort_order=-98)
    #: Configured source name = spool folder name, e.g. ``fortigate``, ``core-r1``.
    source: Mapped[str] = mapped_column(Text, nullable=False, sort_order=-97)
    #: Sender IP address as received by the collector.
    sender: Mapped[str] = mapped_column(INET, nullable=False, sort_order=-96)
    #: Fields the parser did not map to a column (nothing is thrown away).
    extra: Mapped[dict[str, Any]] = mapped_column(
        JSONB, nullable=False, server_default=text("'{}'::jsonb"), sort_order=990
    )
    #: Site day (Europe/Istanbul receive day) of the spool file.
    raw_day: Mapped[date] = mapped_column(Date, nullable=False, sort_order=991)
    #: 1-based line number in ``spool/<source>/<raw_day>.log`` (and in the sealed ``.log.gz``).
    raw_line: Mapped[int] = mapped_column(Integer, nullable=False, sort_order=992)
    #: Byte offset of the line start in the uncompressed file.
    raw_offset: Mapped[int] = mapped_column(BigInteger, nullable=False, sort_order=993)


def _ts_args(table: str, *indexes: Index, comment: str) -> tuple[Any, ...]:
    """Primary key ``(time, id)`` plus the table's own indexes."""
    return (
        PrimaryKeyConstraint("time", "id", name=f"pk_{table}"),
        *indexes,
        {"comment": comment},
    )


class Message(TimeSeries, Base):
    """Every received message, lightweight (spec 7.3 ``messages``)."""

    __tablename__ = "messages"
    __table_args__ = _ts_args(
        "messages",
        Index("ix_messages_source_time", "source", "time"),
        Index("ix_messages_type_time", "type", "time"),
        comment="Every received syslog message (lightweight); raw reference to the spool line.",
    )

    #: Syslog severity 0-7 from PRI (``None`` without PRI).
    severity: Mapped[int | None] = mapped_column(SmallInteger)
    #: Syslog facility 0-23 from PRI.
    facility: Mapped[int | None] = mapped_column(SmallInteger)
    #: Syslog program/tag, or the MikroTik topics string as sent (e.g. ``dhcp,info``).
    program: Mapped[str | None] = mapped_column(Text)
    #: Host name from the syslog header or FortiGate ``devname``.
    host: Mapped[str | None] = mapped_column(Text)
    #: traffic, utm, event, dhcp, arp, fw, account, interface, config, system, heartbeat, unknown…
    type: Mapped[str] = mapped_column(Text, nullable=False)
    subtype: Mapped[str | None] = mapped_column(Text)
    #: Short human-readable text (decoded, truncated).
    text: Mapped[str] = mapped_column(Text, nullable=False, server_default="")
    #: Pattern name when the line could not be parsed (also counted in ``parse_failures``).
    parse_error: Mapped[str | None] = mapped_column(Text)


