class Source(Base):
    """A device that sends syslog (mirrors ``[[sources]]`` in the TOML plus discovered senders)."""

    __tablename__ = "sources"
    __table_args__ = (
        CheckConstraint(_in("type", SOURCE_TYPES), name="type"),
        CheckConstraint("heartbeat_minutes BETWEEN 1 AND 1440", name="heartbeat_minutes"),
        {"comment": "Log sources (configured and discovered senders)."},
    )

    name: Mapped[str] = mapped_column(Text, primary_key=True)
    type: Mapped[str] = mapped_column(Text, nullable=False)
    address: Mapped[str | None] = mapped_column(INET)
    enabled: Mapped[bool] = mapped_column(Boolean, nullable=False, server_default="true")
    #: Expected to send every day (a silent expected source is a gap).
    expected: Mapped[bool] = mapped_column(Boolean, nullable=False, server_default="true")
    heartbeat_minutes: Mapped[int] = mapped_column(Integer, nullable=False, server_default="15")
    #: Sender not in the configuration (spool name ``unknown-<ip>``); raises "yeni log kaynağı".
    unknown: Mapped[bool] = mapped_column(Boolean, nullable=False, server_default="false")
    first_seen: Mapped[datetime | None] = mapped_column(TZ)
    last_seen: Mapped[datetime | None] = mapped_column(TZ)
    notes: Mapped[str | None] = mapped_column(Text)
    created_at: Mapped[datetime] = _created()
    updated_at: Mapped[datetime] = _updated()


class ParseFailure(Base):
    """Lines that could not be parsed, aggregated per source, day and pattern."""

    __tablename__ = "parse_failures"
    __table_args__ = (
        UniqueConstraint("source", "day", "pattern"),
        {"comment": "Unparsed lines per source/day/pattern with one example raw reference."},
    )

    id: Mapped[int] = mapped_column(BigInteger, Identity(), primary_key=True)
    source: Mapped[str] = mapped_column(Text, nullable=False)
    #: ``raw_day`` of the failed lines.
    day: Mapped[date] = mapped_column(Date, nullable=False)
    pattern: Mapped[str] = mapped_column(Text, nullable=False)
    count: Mapped[int] = mapped_column(BigInteger, nullable=False, server_default="0")
    first_seen: Mapped[datetime] = mapped_column(TZ, nullable=False)
    last_seen: Mapped[datetime] = mapped_column(TZ, nullable=False)
    #: Raw reference of one example: ``(source, day, example_line, example_offset)``.
    example_line: Mapped[int] = mapped_column(Integer, nullable=False)
    example_offset: Mapped[int] = mapped_column(BigInteger, nullable=False)
    #: Last error detail (no raw content beyond what the raw line shows anyway).
    error: Mapped[str | None] = mapped_column(Text)


class IngestOffset(Base):
    """Resume point of the ingest service per spool file."""

    __tablename__ = "ingest_offsets"
    __table_args__ = ({"comment": "Ingest resume point per spool file (source, day)."},)

    source: Mapped[str] = mapped_column(Text, primary_key=True)
    day: Mapped[date] = mapped_column(Date, primary_key=True)
    #: Bytes of complete lines already loaded (next read starts here).
    byte_offset: Mapped[int] = mapped_column(BigInteger, nullable=False, server_default="0")
    #: Number of complete lines already loaded (= ``raw_line`` of the last loaded line).
    line_number: Mapped[int] = mapped_column(Integer, nullable=False, server_default="0")
    updated_at: Mapped[datetime] = _updated()
    #: Set when the day is closed and every line was loaded.
    finished_at: Mapped[datetime | None] = mapped_column(TZ)


