class Department(Base):
    __tablename__ = "departments"
    __table_args__ = (
        {"comment": "Departments of the site (entered by its administrator; none are shipped)."},
    )

    id: Mapped[int] = mapped_column(BigInteger, Identity(), primary_key=True)
    name: Mapped[str] = mapped_column(Text, nullable=False, unique=True)
    notes: Mapped[str | None] = mapped_column(Text)
    created_at: Mapped[datetime] = _created()


class Vlan(Base):
    """VLANs and subnets of the site (spec 2.2; the site's own data, none are shipped).

    The primary key is the subnet because a network may have no VLAN id (e.g. a transit network
    between the core router and the FortiGate); ``vlan_id`` is unique where present.
    """

    __tablename__ = "vlans"
    __table_args__ = (
        CheckConstraint("vlan_id BETWEEN 1 AND 4094", name="vlan_id"),
        {"comment": "VLANs/subnets (spec 2.2); department default for devices in the VLAN."},
    )

    subnet: Mapped[str] = mapped_column(CIDR, primary_key=True)
    vlan_id: Mapped[int | None] = mapped_column(Integer, unique=True)
    name_tr: Mapped[str] = mapped_column(Text, nullable=False)
    purpose: Mapped[str | None] = mapped_column(Text)
    #: DHCP server name on the MikroTik router (e.g. ``dhcp60``); NULL for static or
    #: non-MikroTik networks.
    dhcp_server: Mapped[str | None] = mapped_column(Text, unique=True)
    department_id: Mapped[int | None] = mapped_column(
        BigInteger, ForeignKey("departments.id", ondelete="SET NULL")
    )
    #: Guest network (e.g. a guest Wi-Fi that does not leave through the FortiGate, so only
    #: DHCP/ARP evidence exists for it).
    guest: Mapped[bool] = mapped_column(Boolean, nullable=False, server_default="false")
    notes: Mapped[str | None] = mapped_column(Text)
    updated_at: Mapped[datetime] = _updated()


class Person(Base):
    __tablename__ = "persons"
    __table_args__ = ({"comment": "Persons (entered by hand or CSV)."},)

    id: Mapped[int] = mapped_column(BigInteger, Identity(), primary_key=True)
    name: Mapped[str] = mapped_column(Text, nullable=False)
    department_id: Mapped[int | None] = mapped_column(
        BigInteger, ForeignKey("departments.id", ondelete="SET NULL"), index=True
    )
    title: Mapped[str | None] = mapped_column(Text)
    email: Mapped[str | None] = mapped_column(Text)
    employee_no: Mapped[str | None] = mapped_column(Text, unique=True)
    active: Mapped[bool] = mapped_column(Boolean, nullable=False, server_default="true")
    notes: Mapped[str | None] = mapped_column(Text)
    created_at: Mapped[datetime] = _created()
    updated_at: Mapped[datetime] = _updated()
    #: Area U: left out of every person-level usage view and report (company and department
    #: totals still count the traffic). Revision ``0010_usage``.
    usage_excluded: Mapped[bool] = mapped_column(
        Boolean, nullable=False, server_default="false", sort_order=902
    )


class Device(Base):
    """A network device identified by its MAC address (spec 9.2)."""

    __tablename__ = "devices"
    __table_args__ = (
        CheckConstraint(_in("type", DEVICE_TYPES), name="type"),
        Index("ix_devices_last_ip", "last_ip"),
        {"comment": "Devices by MAC address, optionally linked to a person."},
    )

    mac: Mapped[str] = mapped_column(MACADDR, primary_key=True)
    #: Label shown in the attribution chain, e.g. "Planlama-PC-14".
    name: Mapped[str | None] = mapped_column(Text)
    first_seen: Mapped[datetime | None] = mapped_column(TZ)
    last_seen: Mapped[datetime | None] = mapped_column(TZ)
    last_ip: Mapped[str | None] = mapped_column(INET)
    last_vlan: Mapped[int | None] = mapped_column(Integer)
    hostnames: Mapped[list[str]] = mapped_column(
        ARRAY(Text), nullable=False, server_default=text("'{}'::text[]")
    )
    vendor: Mapped[str | None] = mapped_column(Text)
    #: Locally administered (randomised/private) MAC address.
    randomized: Mapped[bool] = mapped_column(Boolean, nullable=False, server_default="false")
    #: pc, phone, printer, ip_phone, ap, server, camera, other (NULL = unknown).
    type: Mapped[str | None] = mapped_column(Text)
    #: Current owner: the person of the open ``device_assignments`` row (denormalised, written
    #: only by :mod:`arcilogger_db.assignments` in the same transaction as the history).
    person_id: Mapped[int | None] = mapped_column(
        BigInteger, ForeignKey("persons.id", ondelete="SET NULL"), index=True
    )
    #: Routers, switches, firewall: excluded from IP conflict detection.
    infrastructure: Mapped[bool] = mapped_column(Boolean, nullable=False, server_default="false")
    notes: Mapped[str | None] = mapped_column(Text)
    tags: Mapped[list[str]] = mapped_column(
        ARRAY(Text), nullable=False, server_default=text("'{}'::text[]")
    )
    created_at: Mapped[datetime] = _created()
    updated_at: Mapped[datetime] = _updated()


class DeviceAssignment(Base):
    """Who a device was assigned to, and when (spec 9.2, ADR-0008).

    ``[valid_from, valid_to)``; ``valid_to`` NULL = the current assignment. At most one open row
    per MAC (partial unique index) and no two overlapping intervals of one MAC — enforced by the
    database itself (revision ``0008_device_assignments``: a ``btree_gist`` exclusion constraint,
    or a trigger where the extension cannot be created). Unassigning closes the open row; rows
    are never deleted. ``devices.person_id`` mirrors the open row (same transaction).
    """

    __tablename__ = "device_assignments"
    __table_args__ = (
        CheckConstraint("valid_to IS NULL OR valid_to >= valid_from", name="valid_interval"),
        Index(
            "uq_device_assignments_open_mac",
            "mac",
            unique=True,
            postgresql_where=text("valid_to IS NULL"),
        ),
        Index("ix_device_assignments_mac_valid_from", "mac", "valid_from"),
        {"comment": "Device-person assignment history (who held a MAC when); never deleted."},
    )

    id: Mapped[int] = mapped_column(BigInteger, Identity(), primary_key=True)
    #: Devices are never deleted; RESTRICT keeps the history if one ever is.
    mac: Mapped[str] = mapped_column(
        MACADDR, ForeignKey("devices.mac", ondelete="RESTRICT"), nullable=False
    )
    person_id: Mapped[int] = mapped_column(
        BigInteger, ForeignKey("persons.id", ondelete="RESTRICT"), nullable=False, index=True
    )
    valid_from: Mapped[datetime] = mapped_column(TZ, nullable=False)
    #: End of the assignment (exclusive); NULL while it is the device's current one.
    valid_to: Mapped[datetime | None] = mapped_column(TZ)
    #: ARCILOGGER user name of whoever made it (``:migration`` for the backfill).
    assigned_by: Mapped[str] = mapped_column(Text, nullable=False)
    note: Mapped[str | None] = mapped_column(Text)
    #: Created by the migration from a link that existed before the history was kept:
    #: ``valid_from`` is then the device's first sighting, not the real start.
    backfilled: Mapped[bool] = mapped_column(Boolean, nullable=False, server_default="false")
    created_at: Mapped[datetime] = _created()


class Lease(Base):
    """IP ↔ MAC interval derived from DHCP and ARP evidence (spec 9.1)."""

    __tablename__ = "leases"
    __table_args__ = (
        CheckConstraint(_in("end_reason", LEASE_END_REASONS), name="end_reason"),
        CheckConstraint(_in("confidence", CONFIDENCE_LEVELS), name="confidence"),
        CheckConstraint('"end" IS NULL OR "end" >= start', name="end_after_start"),
        CheckConstraint("(end_reason = 'open') = (\"end\" IS NULL)", name="open_iff_no_end"),
        Index("ix_leases_ip_start", "ip", "start"),
        Index("ix_leases_mac_start", "mac", "start"),
        {"comment": "Lease timeline: which MAC held which IP when (derived, rebuildable)."},
    )

    id: Mapped[int] = mapped_column(BigInteger, Identity(), primary_key=True)
    ip: Mapped[str] = mapped_column(INET, nullable=False)
    mac: Mapped[str] = mapped_column(MACADDR, nullable=False)
    vlan: Mapped[int | None] = mapped_column(Integer)
    #: DHCP server name (NULL for ARP-derived intervals).
    server: Mapped[str | None] = mapped_column(Text)
    hostname: Mapped[str | None] = mapped_column(Text)
    start: Mapped[datetime] = mapped_column(TZ, nullable=False)
    #: NULL while the interval is open. SQL keyword: quote it as ``"end"`` in raw SQL.
    end: Mapped[datetime | None] = mapped_column(TZ)
    end_reason: Mapped[str] = mapped_column(Text, nullable=False, server_default="open")
    confidence: Mapped[str] = mapped_column(Text, nullable=False)
    #: Table the interval was built from: ``mt_dhcp`` or ``mt_arp``.
    source_table: Mapped[str] = mapped_column(Text, nullable=False)
    #: Time of the latest evidence that kept the interval alive (timeout is computed from it).
    last_evidence: Mapped[datetime | None] = mapped_column(TZ)
    #: Evidence references: a list of ``arcilogger_worker.lookup.EvidenceRef.to_dict()`` objects,
    #: ``{"table", "row_id", "time", "raw": {source, day, line, offset} | null, "summary"}``.
    evidence: Mapped[list[Any]] = mapped_column(
        JSONB, nullable=False, server_default=text("'[]'::jsonb")
    )
    created_at: Mapped[datetime] = _created()
    updated_at: Mapped[datetime] = _updated()


