class User(Base):
    """An ARCILOGGER user (web interface login)."""

    __tablename__ = "users"
    __table_args__ = (
        CheckConstraint(_in("role", ROLES), name="role"),
        CheckConstraint("username ~ '^[a-z0-9][a-z0-9._-]{1,63}$'", name="username"),
        CheckConstraint("failed_attempts >= 0", name="failed_attempts"),
        {"comment": "Users of the web interface (Argon2id password hashes, TOTP)."},
    )

    id: Mapped[int] = mapped_column(BigInteger, Identity(), primary_key=True)
    #: Lower-case ASCII login name (unique).
    username: Mapped[str] = mapped_column(Text, nullable=False, unique=True)
    display_name: Mapped[str] = mapped_column(Text, nullable=False)
    email: Mapped[str | None] = mapped_column(Text)
    #: admin (Yönetici), auditor (Denetçi), hr (İK Raporları), viewer (Rapor İzleyici).
    role: Mapped[str] = mapped_column(Text, nullable=False)
    #: Argon2id hash (PHC string).
    password_hash: Mapped[str] = mapped_column(Text, nullable=False)
    must_change_password: Mapped[bool] = mapped_column(
        Boolean, nullable=False, server_default="true"
    )
    password_changed_at: Mapped[datetime | None] = mapped_column(TZ)
    #: TOTP secret, encrypted (never stored or logged in plain text).
    totp_secret_encrypted: Mapped[str | None] = mapped_column(Text)
    totp_enabled: Mapped[bool] = mapped_column(Boolean, nullable=False, server_default="false")
    #: Last accepted TOTP time step (prevents replay of the same code).
    totp_last_counter: Mapped[int | None] = mapped_column(BigInteger)
    failed_attempts: Mapped[int] = mapped_column(Integer, nullable=False, server_default="0")
    locked_until: Mapped[datetime | None] = mapped_column(TZ)
    last_login: Mapped[datetime | None] = mapped_column(TZ)
    active: Mapped[bool] = mapped_column(Boolean, nullable=False, server_default="true")
    created_at: Mapped[datetime] = _created()
    updated_at: Mapped[datetime] = _updated()


class UserRecoveryCode(Base):
    __tablename__ = "user_recovery_codes"
    __table_args__ = ({"comment": "Hashed one-time recovery codes for TOTP."},)

    id: Mapped[int] = mapped_column(BigInteger, Identity(), primary_key=True)
