    __tablename__ = "user_sessions"
    __table_args__ = (
        CheckConstraint("token_hash ~ '^[0-9a-f]{64}$'", name="token_hash"),
        CheckConstraint("csrf_token_hash ~ '^[0-9a-f]{64}$'", name="csrf_token_hash"),
        {"comment": "Login sessions (SHA-256 of the cookie token; idle and absolute expiry)."},
    )

    #: Lower-case hex SHA-256 of the session token from the ``arci_session`` cookie.
    token_hash: Mapped[str] = mapped_column(Text, primary_key=True)
    user_id: Mapped[int] = mapped_column(
        BigInteger, ForeignKey("users.id", ondelete="CASCADE"), nullable=False, index=True
    )
    created_at: Mapped[datetime] = mapped_column(TZ, nullable=False, server_default=func.now())
    last_seen_at: Mapped[datetime] = mapped_column(TZ, nullable=False, server_default=func.now())
    expires_absolute: Mapped[datetime] = mapped_column(TZ, nullable=False)
    ip: Mapped[str | None] = mapped_column(INET)
    user_agent: Mapped[str | None] = mapped_column(Text)
    #: Password and (where required) TOTP passed.
