class AuditLog(Base):
    """Hash-chained ARCILOGGER audit log (spec 8.5); see ``arcilogger_api.audit``.

    No foreign key on ``actor_id`` on purpose: a later change to the users table must never
    change a hashed audit row. UPDATE, DELETE and TRUNCATE are rejected by a trigger.
    ``prev_hash`` is unique: two entries can never continue the same predecessor (no fork).
    """

    __tablename__ = "audit_log"
    __table_args__ = (
        CheckConstraint("hash ~ '^[0-9a-f]{64}$'", name="hash"),
        CheckConstraint("prev_hash ~ '^[0-9a-f]{64}$'", name="prev_hash"),
        Index("ix_audit_log_time", "time"),
        Index("ix_audit_log_actor_id_time", "actor_id", "time"),
        {"comment": "Hash-chained audit log; exported daily into the sealed vault."},
    )

    id: Mapped[int] = mapped_column(BigInteger, Identity(), primary_key=True)
    time: Mapped[datetime] = mapped_column(TZ, nullable=False)
    actor_id: Mapped[int | None] = mapped_column(BigInteger)
    actor_username: Mapped[str | None] = mapped_column(Text)
    action: Mapped[str] = mapped_column(Text, nullable=False)
    target: Mapped[str | None] = mapped_column(Text)
    details: Mapped[dict[str, Any]] = mapped_column(
        JSONB, nullable=False, server_default=text("'{}'::jsonb")
    )
    ip: Mapped[str | None] = mapped_column(INET)
    prev_hash: Mapped[str] = mapped_column(Text, nullable=False, unique=True)
    hash: Mapped[str] = mapped_column(Text, nullable=False, unique=True)


class Lookup(Base):
    """A 5651 lookup with the request details the user had to enter (spec 9.5, 12.3 page 6:
    makam, dosya/evrak no, talep tarihi and gerekçe are all required, also for internal
    lookups)."""

    __tablename__ = "lookups"
    __table_args__ = (
        CheckConstraint(_in("mode", LOOKUP_MODES), name="mode"),
        CheckConstraint(
            "btrim(authority) <> '' AND btrim(file_no) <> '' AND btrim(reason) <> ''",
            name="request_details",
        ),
        Index("ix_lookups_created_at", "created_at"),
        {"comment": "5651 lookups: request details, query, outcome."},
    )

    id: Mapped[int] = mapped_column(BigInteger, Identity(), primary_key=True)
    created_at: Mapped[datetime] = _created()
    user_id: Mapped[int | None] = mapped_column(
        BigInteger, ForeignKey("users.id", ondelete="SET NULL"), index=True
    )
    username: Mapped[str] = mapped_column(Text, nullable=False)
    #: Requesting authority (makam).
    authority: Mapped[str] = mapped_column(Text, nullable=False)
    #: File / document number (dosya / evrak no).
    file_no: Mapped[str] = mapped_column(Text, nullable=False)
    #: Date of the request (talep tarihi).
    request_date: Mapped[date] = mapped_column(Date, nullable=False)
    #: Reason / reference (gerekçe); required before results are shown.
    reason: Mapped[str] = mapped_column(Text, nullable=False)
    #: ``LookupRequest.to_dict()``.
    query: Mapped[dict[str, Any]] = mapped_column(JSONB, nullable=False)
    #: ``LookupOutcome.to_dict()``; NULL until the lookup finished.
    outcome: Mapped[dict[str, Any] | None] = mapped_column(JSONB)
    mode: Mapped[str | None] = mapped_column(Text)
    result_count: Mapped[int] = mapped_column(Integer, nullable=False, server_default="0")
    finished_at: Mapped[datetime | None] = mapped_column(TZ)


class LookupReport(Base):
    """The official PDF report of a lookup ("Resmi Rapor", spec 9.5).

    Rendered **once**, stored under ``exports/reports/`` and served unchanged afterwards, so its
    SHA-256 (the "ARCILOGGER imza özeti") stays valid. ``inputs`` holds everything the PDF was
    rendered from: rendering them again gives the same bytes.
    """

    __tablename__ = "lookup_reports"
    __table_args__ = (
        UniqueConstraint("lookup_id"),
        CheckConstraint("sha256 ~ '^[0-9a-f]{64}$'", name="sha256"),
        CheckConstraint(
            _in("timestamp_status", REPORT_TIMESTAMP_STATUSES), name="timestamp_status"
        ),
        {"comment": "Official PDF reports of 5651 lookups (file in exports/reports/, SHA-256)."},
    )

    id: Mapped[int] = mapped_column(BigInteger, Identity(), primary_key=True)
    lookup_id: Mapped[int] = mapped_column(
        BigInteger, ForeignKey("lookups.id", ondelete="CASCADE"), nullable=False
    )
    created_at: Mapped[datetime] = _created()
    #: Who generated the report (may differ from the lookup's operator: an administrator).
    user_id: Mapped[int | None] = mapped_column(
        BigInteger, ForeignKey("users.id", ondelete="SET NULL")
    )
    username: Mapped[str] = mapped_column(Text, nullable=False)
    #: Path relative to the ``exports`` directory, e.g. ``reports/ARCILOGGER-5651-rapor-17.pdf``.
    path: Mapped[str] = mapped_column(Text, nullable=False)
    #: SHA-256 of the PDF bytes (lower-case hex).
    sha256: Mapped[str] = mapped_column(Text, nullable=False)
    size: Mapped[int] = mapped_column(BigInteger, nullable=False)
    pages: Mapped[int] = mapped_column(Integer, nullable=False)
    #: ARCILOGGER version that rendered it.
    version: Mapped[str] = mapped_column(Text, nullable=False)
    #: The rendering inputs (``arcilogger_api.reports.inputs.build_inputs``).
    inputs: Mapped[dict[str, Any]] = mapped_column(JSONB, nullable=False)
    timestamp_status: Mapped[str] = mapped_column(
        Text, nullable=False, server_default="not_requested"
    )
    #: Provider, legal grade, serial, genTime, TSA, token file and its verification.
    timestamp: Mapped[dict[str, Any] | None] = mapped_column(JSONB)
    download_count: Mapped[int] = mapped_column(Integer, nullable=False, server_default="0")


class EvidencePackage(Base):
    """An evidence package (ZIP) in ``exports/`` (spec 9.6).

    The API inserts the row as ``queued`` and builds the ZIP in the background
    (``arcilogger_api.evidence_jobs``); ``path`` stays empty until the package is ``ready``.
    The password of a protected package is never stored.
    """

    __tablename__ = "evidence_packages"
    __table_args__ = (
        CheckConstraint(_in("status", EVIDENCE_STATUSES), name="status"),
        CheckConstraint("verifier_sha256 ~ '^[0-9a-f]{64}$'", name="verifier_sha256"),
        CheckConstraint("index_sha256 ~ '^[0-9a-f]{64}$'", name="index_sha256"),
        {"comment": "Evidence packages (ZIP files in exports/, kept 30 days by default)."},
    )

    id: Mapped[int] = mapped_column(BigInteger, Identity(), primary_key=True)
    created_at: Mapped[datetime] = _created()
    user_id: Mapped[int | None] = mapped_column(
        BigInteger, ForeignKey("users.id", ondelete="SET NULL")
    )
    username: Mapped[str] = mapped_column(Text, nullable=False)
    lookup_id: Mapped[int | None] = mapped_column(
        BigInteger, ForeignKey("lookups.id", ondelete="SET NULL"), index=True
    )
    scope: Mapped[dict[str, Any]] = mapped_column(JSONB, nullable=False)
    #: Path relative to the ``exports`` directory.
    path: Mapped[str] = mapped_column(Text, nullable=False)
    sha256: Mapped[str | None] = mapped_column(Text)
    size: Mapped[int | None] = mapped_column(BigInteger)
    password_protected: Mapped[bool] = mapped_column(
        Boolean, nullable=False, server_default="false"
    )
    status: Mapped[str] = mapped_column(Text, nullable=False, server_default="building")
    error: Mapped[str | None] = mapped_column(Text)
    expires_at: Mapped[datetime] = mapped_column(TZ, nullable=False)
    download_count: Mapped[int] = mapped_column(Integer, nullable=False, server_default="0")
    #: The package id written into ``paket.json`` (``KP-YYYYMMDD-HHMMSS-<scope hash>``).
    package_name: Mapped[str | None] = mapped_column(Text)
    #: SHA-256 of the package's ``paket.json`` and of its ``verify.py`` (``PackageInfo``); the
    #: verifier hash is handed to the recipient apart from the package (auditor guide 4).
    index_sha256: Mapped[str | None] = mapped_column(Text)
    verifier_sha256: Mapped[str | None] = mapped_column(Text)
    #: True: every day claims Kamu SM production and chains to a root listed in
    #: ``tsa.legal_root_fingerprints``; False: a test/mock stamped day; NULL: not built, or
    #: claimed but not every root listed (``arcilogger_api.evidence_jobs.package_legal_grade``).
    legal_grade: Mapped[bool | None] = mapped_column(Boolean)
    finished_at: Mapped[datetime | None] = mapped_column(TZ)


class EvidenceDownload(Base):
    __tablename__ = "evidence_downloads"
