    vlan: Mapped[int | None] = mapped_column(Integer)
    online_seconds: Mapped[int] = _seconds()
    active_seconds: Mapped[int] = _seconds()
    download_bytes: Mapped[int] = _bytes()
    upload_bytes: Mapped[int] = _bytes()
