    #: End of the period (exclusive).
    period_to: Mapped[datetime] = mapped_column(TZ, nullable=False)
    person_level: Mapped[bool] = mapped_column(Boolean, nullable=False)
    pseudonymize: Mapped[bool] = mapped_column(Boolean, nullable=False)
