    #: The schedule's recipients when the run was queued.
    recipients: Mapped[list[str]] = mapped_column(
        ARRAY(Text), nullable=False, server_default=text("'{}'::text[]")
    )
    #: False: files only, no e-mail ("run now" with ``send: false``).
    send: Mapped[bool] = mapped_column(Boolean, nullable=False, server_default="true")
    status: Mapped[str] = mapped_column(Text, nullable=False, server_default="queued")
    triggered_by: Mapped[str] = mapped_column(Text, nullable=False)
    #: User name of a "run now"; NULL for scheduled runs.
    requested_by: Mapped[str | None] = mapped_column(Text)
    #: The schedule's occurrence this run is for (scheduled runs).
    due_at: Mapped[datetime | None] = mapped_column(TZ)
    #: Run late, after the worker was stopped (``reports.catch_up``); only the newest missed
    #: occurrence runs.
